/* Function assigned for the Cortex-M33 (Core #0) */
void BOARD_InitPins(void)
{
	/* ISP pin固定是P0_5,由硬件定死，不能修改; */
    /* Enables the clock for the I/O controller.: Enable Clock. */
    CLOCK_EnableClock(kCLOCK_Iocon);
    //------------------------------------------------------------------------------------------
    /* Config SPI0 Pin */
    SPI1_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config SPI1 Pin */
    SPI4_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config SPI2 Pin */
    SPI5_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config SPI3 Pin */
    SPI7_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config SPI4 Pin */
//    SPI4_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config SPI6 Pin */
//    SPI6_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config SPI7 Pin */
    //SPI7_IO_Config();
    //------------------------------------------------------------------------------------------
    /* Config HallPower pin and Pull down DC pin for Powering hall sensor */
    IOConfig_HallPower();
    //------------------------------------------------------------------------------------------
    /* Config DC pin and Pull up DC pin for Powering MCU */
//    IOConfig_DC();
    //------------------------------------------------------------------------------------------
    /* Config Discharge pin and Pull up Discharge pin to avoid discharging */
    IOConfig_Discharge();
    //------------------------------------------------------------------------------------------
    /* Config Uart pin */
    IOConfig_Uart();
    //------------------------------------------------------------------------------------------
    /* Config FlashIC SPI pin */
//    IOConfig_FlashIC_SPI();
    //------------------------------------------------------------------------------------------
    /* Config Test pin */
    IOConfig_TestPin();
    //------------------------------------------------------------------------------------------
}
/* FUNCTION ************************************************************************************************************
 *
 * Function Name : SPI0_IO_Config
 * Description   : SConfig SPI0 IO pin.
 *
 * END ****************************************************************************************************************/
static void SPI1_IO_Config(void)
{

    /*---------------------------Config SPI0 Pin---------------------------------*/
//	const uint32_t port0_pin31_config = (/* Pin is configured as FC0_CTS_SDAX_SSEL0 */
//										IOCON_PIO_FUNC1 |
//										/* No addition pin function */
//										IOCON_PIO_MODE_INACT |
//										/* Standard mode, output slew rate control is enabled */
//										IOCON_PIO_SLEW_STANDARD |
//										/* Input function is not inverted */
//										IOCON_PIO_INV_DI |
//										/* Enables digital function */
//										IOCON_PIO_DIGITAL_EN |
//										/* Open drain is disabled */
//										IOCON_PIO_OPENDRAIN_DI);
//	/* PORT0 PIN29 (coords: 92) is configured as FC0_RTS_SCLX_SSEL1 */
//	IOCON_PinMuxSet(IOCON, SPI0_SEL_PORT, SPI0_SEL_PIN, port0_pin31_config);

	const uint32_t port1_pin9_config = (/* Pin is configured as FC0_SCK */
										 IOCON_PIO_FUNC2 |
										 /* No addition pin function */
										 IOCON_PIO_MODE_INACT |
										 /* Standard mode, output slew rate control is enabled */
										 IOCON_PIO_SLEW_STANDARD |
										 /* Input function is not inverted */
										 IOCON_PIO_INV_DI |
										 /* Enables digital function */
										 IOCON_PIO_DIGITAL_EN |
										 /* Open drain is disabled */
										 IOCON_PIO_OPENDRAIN_DI);
	/* P1_9 configured as FC1_SCK (SPI1 CLK) */
	IOCON_PinMuxSet(IOCON, SPI1_CLK_PORT, SPI1_CLK_PIN, port1_pin9_config);

	/* NOTE: P0_13 is an I2C-tolerant pad on LPC55S28.
	 * Default EGP=0 puts the pin in I2C mode with a 50ns glitch filter on input.
	 * For SPI use we MUST set EGP=1 (GPIO/SPI mode), otherwise the input data is
	 * delayed ~50ns which at 12MHz SCK shifts received data by 1 bit. */
	const uint32_t port0_pin13_config = (/* Pin is configured as FC1_RXD_SDA_MOSI (SPI1 MOSI) */
										 IOCON_PIO_FUNC5 |
										 IOCON_PIO_MODE_INACT |
										 IOCON_PIO_SLEW_STANDARD |
										 IOCON_PIO_INV_DI |
										 IOCON_PIO_DIGITAL_EN |
										 IOCON_PIO_OPENDRAIN_DI |
										 /* CRITICAL: switch I2C-tolerant pad to GPIO/SPI mode */
										 IOCON_PIO_EGP_GPIO |
										 /* disable I2C 50ns glitch filter */
										 IOCON_PIO_I2CFILTER_DIS);
	/* P0_13 configured as FC1_MOSI (SPI1 MOSI) */
	IOCON_PinMuxSet(IOCON, SPI1_MOSI_PORT, SPI1_MOSI_PIN, port0_pin13_config);

	/* NOTE: P0_14 is also an I2C-tolerant pad. Same EGP=1 fix is required for MISO,
	 * which is the actual root cause of the 1-bit right-shift on received data. */
	const uint32_t port0_pin14_config = (/* Pin is configured as FC1_TXD_SCL_MISO (SPI1 MISO) */
										 IOCON_PIO_FUNC6 |
										 IOCON_PIO_MODE_INACT |
										 IOCON_PIO_SLEW_STANDARD |
										 IOCON_PIO_INV_DI |
										 IOCON_PIO_DIGITAL_EN |
										 IOCON_PIO_OPENDRAIN_DI |
										 /* CRITICAL: switch I2C-tolerant pad to GPIO/SPI mode */
										 IOCON_PIO_EGP_GPIO |
										 /* disable I2C 50ns glitch filter on MISO */
										 IOCON_PIO_I2CFILTER_DIS);
	/* P0_14 configured as FC1_MISO (SPI1 MISO) - FUNC6 is correct for FC1_TXD_SCL_MISO */
	IOCON_PinMuxSet(IOCON, SPI1_MISO_PORT, SPI1_MISO_PIN, port0_pin14_config);
    /*---------------------------Config SPI1 Pin done---------------------------------*/
}
