/* FUNCTION ************************************************************************************************************
 *
 * Function Name : SPI0_IO_Config
 * Description   : SConfig SPI0 IO pin.
 *
 * END ****************************************************************************************************************/
static void IOConfig_HallPower(void)
{
	/*---------------------------Config Hall power Pin---------------------------------------------------*/
	const uint32_t port1_pin5_config = (/* Pin is configured as FC0_RXD_SDA_MOSI_DATA */
										IOCON_PIO_FUNC0 |
										/* No addition pin function */
										IOCON_PIO_MODE_INACT |
										/* Standard mode, output slew rate control is enabled */
										IOCON_PIO_SLEW_STANDARD |
										/* Input function is not inverted */
										IOCON_PIO_INV_DI |
										/* Enables digital function */
										IOCON_PIO_DIGITAL_EN |
										/* Open drain is disabled */
										IOCON_PIO_OPENDRAIN_DI);
	/* PORT0 PIN29 (coords: 92) is configured as FC0_RXD_SDA_MOSI_DATA */
	IOCON_PinMuxSet(IOCON, HALL_PORT_pwrRYMCU_EN, HALL_PIN_pwrRYMCU_EN, port1_pin5_config);
	/*---------------------------------------------------------------------------------------------------*/
	HALLPower_PIN_SET_OUTPUT();
	/*---------------------------------------------------------------------------------------------------*/
	/* 上电后先不要给hall供电 */
	HALLPower_PIN_SET_HIGH();
	/*---------------------------Config Hall power Pin Done----------------------------------------------*/
}
