void FlashCS_PIN_SET_HIGH(void)
{
	GPIO->SET[GPIO_PORT_FlashCS] |= (1 << GPIO_PIN_FlashCS);
}
void FlashCS_PIN_SET_LOW(void)
{
	GPIO->CLR[GPIO_PORT_FlashCS] |= (1 << GPIO_PIN_FlashCS);
}
//------------------------------------------------------------------
void FlashCLK_PIN_SET_OUTPUT(void)
{
	GPIO->DIR[GPIO_PORT_FlashCLK] |= (1 << GPIO_PIN_FlashCLK);
	GPIO->DIRSET[GPIO_PORT_FlashCLK] |= (1 << GPIO_PIN_FlashCLK);
}
void FlashCLK_PIN_SET_HIGH(void)
{
	GPIO->SET[GPIO_PORT_FlashCLK] |= (1 << GPIO_PIN_FlashCLK);
}
void FlashCLK_PIN_SET_LOW(void)
{
	GPIO->CLR[GPIO_PORT_FlashCLK] |= (1 << GPIO_PIN_FlashCLK);
}
//------------------------------------------------------------------
void FlashMOSI_PIN_SET_OUTPUT(void)
{
	GPIO->DIR[GPIO_PORT_FlashMOSI] |= (1 << GPIO_PIN_FlashMOSI);
	GPIO->DIRSET[GPIO_PORT_FlashMOSI] |= (1 << GPIO_PIN_FlashMOSI);
}
void FlashMOSI_PIN_SET_HIGH(void)
{
	GPIO->SET[GPIO_PORT_FlashMOSI] |= (1 << GPIO_PIN_FlashMOSI);
}
void FlashMOSI_PIN_SET_LOW(void)
{
	GPIO->CLR[GPIO_PORT_FlashMOSI] |= (1 << GPIO_PIN_FlashMOSI);
}
//------------------------------------------------------------------
void FlashMISO_PIN_SET_INPUT(void)
{
	GPIO->DIR[GPIO_PORT_FlashMISO] &= GPIO_PIN_FlashMISO_MASK;
	//GPIO->DIRSET[GPIO_PORT_FlashMISO] |= (1 << GPIO_PIN_FlashMISO);
	GPIO->DIRSET[GPIO_PORT_FlashMISO] &= GPIO_PIN_FlashMISO_MASK;
}
uint8_t FlashMISO_PIN_GET_STATE(void)
{
	return ((GPIO->PIN[GPIO_PORT_FlashMISO] & (1 << GPIO_PIN_FlashMISO))>> GPIO_PIN_FlashMISO);
}
//------------------------------------------------------------------

/* FUNCTION ************************************************************************************************************
 *
 * Function Name : HALL_RGB_POWERON()
 * Description   : When device power on, hall sensor should be reset once.
 *
 * END ****************************************************************************************************************/
void HALL_RGB_POWERON(void)
{
	//------------------------------------------------------------------
//	DC_PIN_SET_HIGH();
	HALLPower_PIN_SET_LOW();
	Discharge_PIN_SET_LOW();

	hall_mcu_delay_ms(1);
	HALLPower_PIN_SET_HIGH();
	Discharge_PIN_SET_HIGH();

	hall_mcu_delay_ms(20);
	HALLPower_PIN_SET_LOW();
	Discharge_PIN_SET_LOW();
	//------------------------------------------------------------------
}

